insert into invstock.lib_glossary_terms (slug, term, full_name, vi_name, industry, aliases, short_def, body, formula, example, related, auto_link, match_case) values
('roe','ROE','Return on Equity','Tỷ suất lợi nhuận trên vốn chủ sở hữu','general','{}'::text[],'Lợi nhuận sau thuế chia cho vốn chủ sở hữu bình quân. Cho biết mỗi đồng vốn của cổ đông tạo ra bao nhiêu lợi nhuận trong một năm.','ROE cao và ổn định qua nhiều năm thường là dấu hiệu của lợi thế cạnh tranh. Cần xem ROE đến từ biên lợi nhuận, vòng quay tài sản hay đòn bẩy (phân tích DuPont): ROE cao nhờ vay nợ nhiều thì rủi ro hơn ROE cao nhờ biên lợi nhuận tốt.','ROE = LNST của cổ đông công ty mẹ / Vốn chủ sở hữu bình quân',null,array['ROA','ROIC','D/E']::text[],true,true),
('roa','ROA','Return on Assets','Tỷ suất lợi nhuận trên tổng tài sản','general','{}'::text[],'Lợi nhuận sau thuế chia cho tổng tài sản bình quân. Đo hiệu quả sử dụng toàn bộ tài sản, không phụ thuộc cơ cấu vốn.','Với ngân hàng, ROA khoảng 1,5–2% đã được xem là tốt vì đòn bẩy rất cao. Với doanh nghiệp sản xuất, nên so ROA với doanh nghiệp cùng ngành.','ROA = LNST / Tổng tài sản bình quân',null,array['ROE']::text[],true,true),
('roic','ROIC','Return on Invested Capital','Tỷ suất lợi nhuận trên vốn đầu tư','general','{}'::text[],'Lợi nhuận hoạt động sau thuế (NOPAT) chia cho vốn đầu tư (vốn chủ + nợ vay − tiền mặt dư). Doanh nghiệp tạo giá trị khi ROIC lớn hơn WACC.',null,'ROIC = EBIT × (1 − thuế suất) / (Vốn chủ sở hữu + Nợ vay − Tiền mặt dư thừa)',null,array['WACC','ROE','EBIT']::text[],true,true),
('eps','EPS','Earnings Per Share','Lợi nhuận trên mỗi cổ phiếu','general','{}'::text[],'Lợi nhuận sau thuế thuộc cổ đông công ty mẹ (sau khi trừ quỹ khen thưởng phúc lợi nếu có) chia cho số cổ phiếu lưu hành bình quân.','EPS pha loãng tính thêm cổ phiếu có thể phát sinh từ trái phiếu chuyển đổi, ESOP. Khi so sánh EPS qua các năm cần điều chỉnh cho các đợt chia cổ tức bằng cổ phiếu, phát hành thêm.','EPS = LNST cổ đông công ty mẹ / Số cổ phiếu lưu hành bình quân',null,array['P/E']::text[],true,true),
('bvps','BVPS','Book Value Per Share','Giá trị sổ sách mỗi cổ phiếu','general','{}'::text[],'Vốn chủ sở hữu (không gồm lợi ích cổ đông không kiểm soát) chia cho số cổ phiếu đang lưu hành.',null,null,null,array['P/B']::text[],true,true),
('lnst','LNST','Lợi nhuận sau thuế','Lợi nhuận sau thuế','general',array['lợi nhuận sau thuế']::text[],'Lợi nhuận còn lại sau khi trừ toàn bộ chi phí và thuế thu nhập doanh nghiệp. Trong báo cáo thường tách phần thuộc cổ đông công ty mẹ.',null,null,null,array['EPS','ROE']::text[],true,true),
('lntt','LNTT','Lợi nhuận trước thuế','Lợi nhuận trước thuế','general',array['lợi nhuận trước thuế']::text[],'Lợi nhuận kế toán trước khi trừ thuế thu nhập doanh nghiệp, gồm cả lợi nhuận hoạt động chính, tài chính và khác.',null,null,null,array['LNST','EBIT']::text[],true,true),
('esop','ESOP','Employee Stock Ownership Plan','Cổ phiếu thưởng/ưu đãi cho người lao động','general','{}'::text[],'Chương trình phát hành cổ phiếu cho nhân viên, thường giá thấp hơn thị trường. Làm tăng số cổ phiếu và pha loãng EPS của cổ đông hiện hữu.',null,null,null,array['EPS']::text[],true,true),
('bctc','BCTC','Báo cáo tài chính','Báo cáo tài chính','general','{}'::text[],'Bộ báo cáo gồm bảng cân đối kế toán, kết quả kinh doanh, lưu chuyển tiền tệ và thuyết minh. BCTC kiểm toán năm và soát xét bán niên có độ tin cậy cao hơn BCTC quý tự lập.',null,null,null,'{}'::text[],true,true),
('ebit','EBIT','Earnings Before Interest and Taxes','Lợi nhuận trước lãi vay và thuế','general','{}'::text[],'Lợi nhuận từ hoạt động kinh doanh trước khi trừ chi phí lãi vay và thuế. Dùng để so sánh hiệu quả hoạt động giữa các doanh nghiệp có cơ cấu vốn khác nhau.',null,'EBIT = LNTT + Chi phí lãi vay',null,array['EBITDA','ROIC']::text[],true,true),
('ebitda','EBITDA','Earnings Before Interest, Taxes, Depreciation and Amortization','Lợi nhuận trước lãi vay, thuế và khấu hao','general','{}'::text[],'EBIT cộng lại khấu hao tài sản cố định và phân bổ. Gần đúng với dòng tiền hoạt động trước vốn lưu động, hay dùng cho doanh nghiệp nhiều tài sản cố định.','EBITDA bỏ qua nhu cầu đầu tư thay thế tài sản (CAPEX), nên với doanh nghiệp thâm dụng vốn cần xem thêm FCF.','EBITDA = EBIT + Khấu hao + Phân bổ',null,array['EBIT','EV/EBITDA','FCF']::text[],true,true),
('fcf','FCF','Free Cash Flow','Dòng tiền tự do','general','{}'::text[],'Dòng tiền từ hoạt động kinh doanh trừ chi đầu tư tài sản cố định (CAPEX). Là tiền thực sự có thể dùng trả nợ, chia cổ tức hoặc tái đầu tư.',null,'FCF = CFO − CAPEX',null,array['CFO','CAPEX','FCFF','FCFE']::text[],true,true),
('cfo','CFO','Cash Flow from Operations','Lưu chuyển tiền thuần từ hoạt động kinh doanh','general','{}'::text[],'Tiền thu chi thực tế từ hoạt động kinh doanh chính trong kỳ. CFO thấp hơn nhiều so với LNST kéo dài là dấu hiệu cần soi chất lượng lợi nhuận.',null,null,null,array['FCF','LNST']::text[],true,true),
('capex','CAPEX','Capital Expenditure','Chi đầu tư tài sản cố định','general',array['Capex','capex']::text[],'Tiền chi mua sắm, xây dựng tài sản cố định và tài sản dài hạn để duy trì hoặc mở rộng năng lực sản xuất kinh doanh.',null,null,null,array['FCF']::text[],true,true),
('cagr','CAGR','Compound Annual Growth Rate','Tốc độ tăng trưởng kép hằng năm','general','{}'::text[],'Tốc độ tăng trưởng bình quân mỗi năm nếu tăng đều theo lãi kép trong một giai đoạn.',null,'CAGR = (Giá trị cuối / Giá trị đầu)^(1 / số năm) − 1',null,'{}'::text[],true,true),
('yoy','YoY','Year over Year','So với cùng kỳ năm trước','general',array['yoy']::text[],'Mức thay đổi so với cùng kỳ năm trước, ví dụ quý 3 năm nay so với quý 3 năm ngoái. Loại bỏ được yếu tố mùa vụ.',null,null,null,'{}'::text[],true,true),
('qoq','QoQ','Quarter over Quarter','So với quý liền trước','general',array['qoq']::text[],'Mức thay đổi so với quý liền trước. Phản ánh xu hướng ngắn hạn nhưng chịu ảnh hưởng của mùa vụ.',null,null,null,'{}'::text[],true,true),
('ttm','TTM','Trailing Twelve Months','12 tháng gần nhất','general','{}'::text[],'Tổng số liệu của 4 quý gần nhất. Hay dùng để tính P/E, ROE cập nhật hơn số liệu năm tài chính.',null,null,null,'{}'::text[],true,true),
('d-e','D/E','Debt to Equity','Tỷ lệ nợ vay trên vốn chủ sở hữu','general','{}'::text[],'Nợ vay có chịu lãi chia cho vốn chủ sở hữu. Đo mức đòn bẩy tài chính; một số báo cáo dùng tổng nợ phải trả thay cho nợ vay.',null,'D/E = (Vay ngắn hạn + Vay dài hạn) / Vốn chủ sở hữu',null,array['ROE']::text[],true,true),
('ccc','CCC','Cash Conversion Cycle','Chu kỳ chuyển đổi tiền mặt','general','{}'::text[],'Số ngày từ khi doanh nghiệp chi tiền mua hàng đến khi thu tiền bán hàng. CCC càng ngắn, doanh nghiệp càng ít cần vốn lưu động.',null,'CCC = Số ngày tồn kho (DIO) + Số ngày phải thu (DSO) − Số ngày phải trả (DPO)',null,'{}'::text[],true,true),
('p-e','P/E','Price to Earnings','Hệ số giá trên lợi nhuận','valuation','{}'::text[],'Giá cổ phiếu chia cho EPS. Cho biết nhà đầu tư đang trả bao nhiêu đồng cho một đồng lợi nhuận của doanh nghiệp.','P/E chỉ có ý nghĩa khi so với lịch sử của chính doanh nghiệp, với doanh nghiệp cùng ngành và với tốc độ tăng trưởng (PEG). P/E thấp có thể do thị trường kỳ vọng lợi nhuận giảm.','P/E = Giá cổ phiếu / EPS (thường dùng EPS 4 quý gần nhất hoặc EPS dự phóng)',null,array['EPS','PEG','P/B']::text[],true,true),
('p-b','P/B','Price to Book','Hệ số giá trên giá trị sổ sách','valuation','{}'::text[],'Giá cổ phiếu chia cho giá trị sổ sách mỗi cổ phiếu (BVPS). Hay dùng cho ngân hàng, chứng khoán, bảo hiểm vì tài sản chủ yếu là tài sản tài chính.',null,'P/B = Giá cổ phiếu / BVPS',null,array['BVPS','ROE']::text[],true,true),
('peg','PEG','Price/Earnings to Growth','P/E so với tăng trưởng','valuation','{}'::text[],'P/E chia cho tốc độ tăng trưởng EPS kỳ vọng (tính bằng %). PEG quanh 1 thường được xem là hợp lý với tăng trưởng.',null,'PEG = P/E / Tăng trưởng EPS (%)',null,array['P/E']::text[],true,true),
('ev-ebitda','EV/EBITDA','Enterprise Value to EBITDA','Giá trị doanh nghiệp trên EBITDA','valuation','{}'::text[],'Giá trị doanh nghiệp (vốn hóa + nợ vay − tiền mặt) chia cho EBITDA. Không bị ảnh hưởng bởi cơ cấu vốn và chính sách khấu hao, tiện so sánh giữa các doanh nghiệp.',null,'EV = Vốn hóa + Nợ vay + Lợi ích CĐ không kiểm soát − Tiền và tương đương tiền',null,array['EBITDA']::text[],true,true),
('dcf','DCF','Discounted Cash Flow','Chiết khấu dòng tiền','valuation','{}'::text[],'Phương pháp định giá bằng cách dự phóng dòng tiền tương lai rồi chiết khấu về hiện tại theo chi phí vốn. Kết quả rất nhạy với tăng trưởng dài hạn và tỷ lệ chiết khấu.','Có hai dạng phổ biến: FCFF chiết khấu bằng WACC để ra giá trị doanh nghiệp, hoặc FCFE chiết khấu bằng chi phí vốn chủ để ra giá trị vốn chủ. Giá trị cuối kỳ (terminal value) thường chiếm phần lớn kết quả nên cần kiểm tra độ nhạy.',null,null,array['WACC','FCFF','FCFE']::text[],true,true),
('wacc','WACC','Weighted Average Cost of Capital','Chi phí vốn bình quân gia quyền','valuation','{}'::text[],'Chi phí vốn bình quân của nợ vay (sau thuế) và vốn chủ sở hữu, theo tỷ trọng. Dùng làm tỷ lệ chiết khấu trong DCF dòng tiền FCFF.',null,'WACC = E/(D+E) × Ke + D/(D+E) × Kd × (1 − t)',null,array['DCF','ROIC']::text[],true,true),
('fcff','FCFF','Free Cash Flow to Firm','Dòng tiền tự do của doanh nghiệp','valuation','{}'::text[],'Dòng tiền còn lại cho cả chủ nợ và cổ đông sau khi trừ thuế, đầu tư tài sản cố định và vốn lưu động.',null,'FCFF = EBIT × (1 − t) + Khấu hao − CAPEX − Thay đổi vốn lưu động',null,array['FCFE','DCF']::text[],true,true),
('fcfe','FCFE','Free Cash Flow to Equity','Dòng tiền tự do của vốn chủ sở hữu','valuation','{}'::text[],'Dòng tiền còn lại cho cổ đông sau khi đã trả lãi, trả gốc và vay thêm.',null,'FCFE = FCFF − Lãi vay × (1 − t) + Vay ròng',null,array['FCFF','DCF']::text[],true,true),
('mos','MOS','Margin of Safety','Biên an toàn','valuation','{}'::text[],'Khoảng chênh giữa giá trị hợp lý ước tính và giá thị trường, tính theo % giá trị hợp lý. MOS càng lớn thì càng có đệm cho sai số định giá.',null,'MOS = (Giá trị hợp lý − Giá hiện tại) / Giá trị hợp lý',null,array['DCF']::text[],true,true),
('ddm','DDM','Dividend Discount Model','Mô hình chiết khấu cổ tức','valuation','{}'::text[],'Định giá cổ phiếu bằng giá trị hiện tại của cổ tức kỳ vọng. Phù hợp với doanh nghiệp chia cổ tức tiền mặt đều đặn.',null,null,null,'{}'::text[],true,true),
('nim','NIM','Net Interest Margin','Biên lãi ròng','banking','{}'::text[],'Thu nhập lãi thuần chia cho tài sản sinh lãi bình quân. Đo khả năng kiếm lời từ chênh lệch lãi cho vay và lãi huy động của ngân hàng.','NIM phụ thuộc vào cơ cấu cho vay (bán lẻ thường cao hơn doanh nghiệp lớn), tỷ lệ CASA và chi phí vốn. NIM cao đi kèm cho vay rủi ro cao có thể làm tăng chi phí tín dụng sau này.','NIM = Thu nhập lãi thuần / Tài sản sinh lãi bình quân',null,array['CASA','CoF','YOEA']::text[],true,true),
('casa','CASA','Current Account Savings Account','Tiền gửi không kỳ hạn','banking',array['tỷ lệ CASA']::text[],'Tiền gửi không kỳ hạn (và tiền gửi thanh toán) của khách hàng. Tỷ lệ CASA là CASA chia cho tổng tiền gửi; CASA cao giúp ngân hàng có nguồn vốn rẻ.',null,'Tỷ lệ CASA = Tiền gửi không kỳ hạn / Tổng tiền gửi khách hàng',null,array['NIM','CoF']::text[],true,true),
('ldr','LDR','Loan to Deposit Ratio','Tỷ lệ cho vay trên huy động','banking','{}'::text[],'Dư nợ cho vay chia cho tiền gửi huy động. Phản ánh mức sử dụng vốn huy động; NHNN giới hạn tỷ lệ này (theo cách tính riêng) đối với ngân hàng thương mại.',null,'LDR = Dư nợ cho vay / Tiền gửi khách hàng (cách tính theo quy định NHNN có điều chỉnh các khoản mục)',null,array['CASA']::text[],true,true),
('npl','NPL','Non-Performing Loan','Nợ xấu','banking',array['tỷ lệ nợ xấu']::text[],'Khoản vay thuộc nhóm 3 đến nhóm 5 (dưới tiêu chuẩn, nghi ngờ, có khả năng mất vốn). Tỷ lệ nợ xấu là nợ xấu chia cho tổng dư nợ.','Nên xem cùng nợ nhóm 2 (nợ cần chú ý), nợ tái cơ cấu, nợ bán cho VAMC và tỷ lệ bao phủ nợ xấu (LLR) để thấy đầy đủ chất lượng tài sản.','Tỷ lệ nợ xấu = Nợ nhóm 3–5 / Tổng dư nợ cho vay',null,array['LLR','Credit cost']::text[],true,true),
('llr','LLR','Loan Loss Reserve coverage','Tỷ lệ bao phủ nợ xấu','banking',array['tỷ lệ bao phủ nợ xấu']::text[],'Dự phòng rủi ro cho vay chia cho nợ xấu. Tỷ lệ trên 100% nghĩa là dự phòng đã đủ bù toàn bộ nợ xấu hiện có.',null,'LLR = Dự phòng rủi ro cho vay khách hàng / Nợ xấu (nhóm 3–5)',null,array['NPL','Credit cost']::text[],true,true),
('cir','CIR','Cost to Income Ratio','Tỷ lệ chi phí trên thu nhập','banking','{}'::text[],'Chi phí hoạt động chia cho tổng thu nhập hoạt động (TOI). CIR càng thấp, ngân hàng vận hành càng hiệu quả.',null,'CIR = Chi phí hoạt động / Tổng thu nhập hoạt động',null,array['TOI','PPOP']::text[],true,true),
('car','CAR','Capital Adequacy Ratio','Tỷ lệ an toàn vốn','banking','{}'::text[],'Vốn tự có chia cho tài sản có rủi ro quy đổi. Ngân hàng phải duy trì tối thiểu 8% theo chuẩn Basel II áp dụng tại Việt Nam; CAR thấp giới hạn khả năng tăng trưởng tín dụng.',null,null,null,array['Basel II']::text[],true,true),
('basel-ii','Basel II','Basel II','Chuẩn an toàn vốn Basel II','banking','{}'::text[],'Bộ chuẩn quốc tế về quản trị rủi ro và an toàn vốn của ngân hàng, gồm 3 trụ cột: vốn tối thiểu, giám sát và công bố thông tin.',null,null,null,array['CAR']::text[],true,false),
('cof','CoF','Cost of Funds','Chi phí vốn huy động','banking',array['COF']::text[],'Chi phí lãi phải trả chia cho nguồn vốn chịu lãi bình quân. CoF thấp nhờ CASA cao là lợi thế lớn của ngân hàng.',null,null,null,array['NIM','CASA']::text[],true,true),
('yoea','YOEA','Yield on Earning Assets','Lợi suất tài sản sinh lãi','banking','{}'::text[],'Thu nhập lãi chia cho tài sản sinh lãi bình quân. NIM xấp xỉ bằng YOEA trừ chi phí vốn tính trên tài sản sinh lãi.',null,null,null,array['NIM','CoF']::text[],true,true),
('toi','TOI','Total Operating Income','Tổng thu nhập hoạt động','banking','{}'::text[],'Tổng thu nhập lãi thuần và thu nhập ngoài lãi (phí dịch vụ, kinh doanh ngoại hối, chứng khoán, thu nhập khác) của ngân hàng.',null,null,null,array['CIR','PPOP']::text[],true,true),
('ppop','PPOP','Pre-Provision Operating Profit','Lợi nhuận trước dự phòng','banking','{}'::text[],'Lợi nhuận hoạt động trước khi trích lập dự phòng rủi ro tín dụng. Cho thấy năng lực tạo lợi nhuận cốt lõi trước tác động của nợ xấu.',null,'PPOP = TOI − Chi phí hoạt động',null,array['TOI','Credit cost']::text[],true,true),
('credit-cost','Credit cost','Credit cost','Chi phí tín dụng','banking',array['chi phí tín dụng']::text[],'Chi phí dự phòng rủi ro tín dụng trong kỳ chia cho dư nợ cho vay bình quân. Tăng mạnh khi chất lượng tài sản xấu đi.',null,null,null,array['NPL','LLR']::text[],true,false),
('no-nhom-2','Nợ nhóm 2','Special mention loans','Nợ cần chú ý','banking',array['nợ nhóm 2']::text[],'Khoản vay quá hạn từ 10 đến 90 ngày hoặc có dấu hiệu suy giảm khả năng trả nợ. Chưa phải nợ xấu nhưng là chỉ báo sớm của nợ xấu.',null,null,null,array['NPL']::text[],true,false),
('margin','Margin','Margin lending','Cho vay ký quỹ','securities',array['dư nợ margin','cho vay ký quỹ']::text[],'Công ty chứng khoán cho nhà đầu tư vay tiền để mua chứng khoán, dùng chính chứng khoán làm tài sản bảo đảm. Là nguồn thu lãi lớn của công ty chứng khoán.',null,null,null,array['FVTPL']::text[],true,true),
('fvtpl','FVTPL','Financial assets at Fair Value Through Profit or Loss','Tài sản tài chính ghi nhận theo giá trị hợp lý qua lãi/lỗ','securities','{}'::text[],'Danh mục tự doanh được đánh giá lại theo giá thị trường và đưa chênh lệch vào kết quả kinh doanh. Làm lợi nhuận công ty chứng khoán biến động theo thị trường.',null,null,null,array['AFS','HTM']::text[],true,true),
('afs','AFS','Available-for-Sale financial assets','Tài sản tài chính sẵn sàng để bán','securities','{}'::text[],'Tài sản tài chính không thuộc nhóm FVTPL hay HTM; chênh lệch đánh giá lại ghi vào vốn chủ sở hữu (thu nhập toàn diện khác) thay vì lãi/lỗ.',null,null,null,array['FVTPL','HTM']::text[],true,true),
('htm','HTM','Held-to-Maturity investments','Đầu tư nắm giữ đến ngày đáo hạn','securities','{}'::text[],'Khoản đầu tư có kỳ hạn cố định (tiền gửi, trái phiếu) mà doanh nghiệp có ý định giữ đến khi đáo hạn, ghi nhận theo giá trị phân bổ.',null,null,null,array['FVTPL','AFS']::text[],true,true),
('combined-ratio','Combined ratio','Combined ratio','Tỷ lệ kết hợp','insurance',array['tỷ lệ kết hợp']::text[],'Tổng tỷ lệ bồi thường và tỷ lệ chi phí của doanh nghiệp bảo hiểm phi nhân thọ. Dưới 100% nghĩa là hoạt động bảo hiểm gốc có lãi trước thu nhập đầu tư.',null,'Combined ratio = Tỷ lệ bồi thường + Tỷ lệ chi phí',null,array['Loss ratio']::text[],true,false),
('loss-ratio','Loss ratio','Loss ratio','Tỷ lệ bồi thường','insurance',array['tỷ lệ bồi thường']::text[],'Chi bồi thường chia cho phí bảo hiểm được hưởng trong kỳ.',null,null,null,array['Combined ratio']::text[],true,false),
('presales','Presales','Presales','Doanh số bán hàng trước','real_estate',array['presales','doanh số bán trước']::text[],'Giá trị hợp đồng mua bán bất động sản đã ký nhưng chưa bàn giao nên chưa ghi nhận doanh thu. Là chỉ báo sớm cho doanh thu các năm tới.',null,null,null,array['Backlog','RNAV']::text[],true,true),
('rnav','RNAV','Revalued Net Asset Value','Giá trị tài sản ròng đánh giá lại','real_estate','{}'::text[],'Giá trị tài sản (chủ yếu là quỹ đất, dự án) đánh giá lại theo giá thị trường, trừ nợ phải trả. Phương pháp định giá phổ biến cho doanh nghiệp bất động sản.',null,null,null,array['Quỹ đất']::text[],true,true),
('quy-dat','Quỹ đất','Land bank','Quỹ đất','real_estate',array['quỹ đất']::text[],'Tổng diện tích đất doanh nghiệp đang sở hữu hoặc có quyền phát triển. Cần xem tình trạng pháp lý, chi phí đất đã trả và vị trí, không chỉ diện tích.',null,null,null,array['RNAV']::text[],true,false),
('backlog','Backlog','Order backlog','Giá trị hợp đồng chưa thực hiện','construction',array['backlog']::text[],'Giá trị các hợp đồng đã ký nhưng chưa thực hiện xong. Backlog lớn so với doanh thu năm cho thấy doanh nghiệp có việc làm trong vài năm tới.',null,null,null,array['Book-to-bill','EPC']::text[],true,true),
('book-to-bill','Book-to-bill','Book-to-bill ratio','Tỷ lệ hợp đồng mới trên doanh thu','construction','{}'::text[],'Giá trị hợp đồng ký mới chia cho doanh thu ghi nhận trong kỳ. Trên 1 nghĩa là backlog đang tăng lên.',null,null,null,array['Backlog']::text[],true,false),
('epc','EPC','Engineering, Procurement and Construction','Thiết kế, mua sắm và thi công','construction','{}'::text[],'Hình thức tổng thầu chịu trách nhiệm cả thiết kế, mua sắm thiết bị và thi công, bàn giao công trình hoàn chỉnh cho chủ đầu tư.',null,null,null,'{}'::text[],true,true),
('cong-suat','Công suất','Capacity utilization','Hiệu suất sử dụng công suất','manufacturing',array['hiệu suất sử dụng công suất']::text[],'Sản lượng thực tế chia cho công suất thiết kế. Hiệu suất cao giúp phân bổ chi phí cố định, cải thiện biên lợi nhuận gộp.',null,null,null,array['Biên lợi nhuận gộp']::text[],false,false),
('bien-loi-nhuan-gop','Biên lợi nhuận gộp','Gross margin','Biên lợi nhuận gộp','manufacturing',array['biên lợi nhuận gộp','biên gộp']::text[],'Lợi nhuận gộp chia cho doanh thu thuần. Phản ánh khả năng định giá bán và kiểm soát giá vốn (nguyên vật liệu, nhân công, khấu hao).',null,'Biên gộp = (Doanh thu thuần − Giá vốn hàng bán) / Doanh thu thuần',null,'{}'::text[],true,false),
('ppa','PPA','Power Purchase Agreement','Hợp đồng mua bán điện','energy','{}'::text[],'Hợp đồng dài hạn giữa nhà máy điện và bên mua (thường là EVN) quy định giá, sản lượng và thời hạn mua điện.',null,null,null,array['FIT']::text[],true,true),
('fit','FIT','Feed-in Tariff','Giá điện hỗ trợ cố định','energy','{}'::text[],'Cơ chế giá mua điện cố định trong thời gian dài (thường 20 năm) để khuyến khích điện mặt trời, điện gió.',null,null,null,array['PPA']::text[],true,true),
('sssg','SSSG','Same-Store Sales Growth','Tăng trưởng doanh thu cửa hàng hiện hữu','consumer','{}'::text[],'Tăng trưởng doanh thu của các cửa hàng đã hoạt động ít nhất một năm, loại trừ tác động mở mới. Đo sức khỏe thực của chuỗi bán lẻ.',null,null,null,'{}'::text[],true,true),
('free-float','Free float','Free float','Tỷ lệ cổ phiếu tự do chuyển nhượng','market',array['free-float']::text[],'Phần cổ phiếu có thể giao dịch tự do trên thị trường, không tính cổ phiếu của cổ đông chiến lược, nhà nước, nội bộ hoặc bị hạn chế chuyển nhượng.',null,null,null,array['ADTV']::text[],true,false),
('adtv','ADTV','Average Daily Trading Value','Giá trị giao dịch bình quân ngày','market','{}'::text[],'Giá trị giao dịch bình quân mỗi phiên trong một khoảng thời gian (ví dụ 20 phiên). Đo thanh khoản cổ phiếu.',null,null,null,array['Free float']::text[],true,true),
('room-ngoai','Room ngoại','Foreign ownership limit','Giới hạn sở hữu nước ngoài','market',array['room ngoại']::text[],'Tỷ lệ sở hữu tối đa của nhà đầu tư nước ngoài tại một doanh nghiệp. Khi hết room, cổ phiếu có thể giao dịch thỏa thuận với giá cao hơn thị trường.',null,null,null,'{}'::text[],true,false)
